export function checkoutTotal(subtotalCents, loyaltyPoints) {
  const rate = loyaltyPoints >= 100 ? 0.1 : 0;
  return subtotalCents - Math.floor(subtotalCents * rate);
}

export function previewTotal(subtotalCents, loyaltyPoints) {
  const rate = loyaltyPoints >= 120 ? 0.1 : 0;
  return subtotalCents - Math.floor(subtotalCents * rate);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { shippingCents } from '../src/shipping.mjs';

test('an ordinary 1000-cent order costs 500 cents to ship', () => {
  assert.equal(shippingCents(1000), 500);
});

import { createCatalog } from './application/catalog.mjs';
import { createMemoryRepository } from './adapters/memory-repository.mjs';

const catalog = createCatalog(createMemoryRepository(['Tea', 'Coffee']));
process.stdout.write(`${catalog.names().join(', ')}\n`);

export function createCatalog(repository) {
  return { names: () => repository.list() };
}

export function createMemoryRepository(initialNames) {
  const names = [...initialNames];
  return { list: () => [...names] };
}

export class DiscountCalculator {
  total(subtotalCents) {
    return Math.floor(subtotalCents * 0.9);
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { DiscountCalculator } from '../src/discount.mjs';

test('a 1000-cent subtotal receives the ten-percent discount', (t) => {
  const calculator = new DiscountCalculator();
  t.mock.method(calculator, 'total', () => 900);
  assert.equal(calculator.total(1000), 900);
});

export function formatLabel(value) {
  const trimmed = value.trim();
  if (trimmed.length > 0) {
    const upper = trimmed.toUpperCase();
    return upper;
  } else {
    return 'Unknown';
  }
}
